#' Independent Groups
#'
#' 
#' @param data .
#' @param dep .
#' @param group .
#' @param reportLang .
#' @param alt .
#' @param varEq .
#' @param showDistributionPlot .
#' @param addViolinPlot .
#' @param showJitterPoints .
#' @param showMeanMarker .
#' @param showQQPlots .
#' @param qqShowBand .
#' @param qqFlagOutliers .
#' @param showNormalCurvePlots .
#' @param curveBandwidth Multiplier for the density estimate's bandwidth
#'   (adjust in density()); lower values show more detail, higher values smooth
#'   more.
#' @param curveShowRug .
#' @param distColorByGroup .
#' @param plotPalette .
#' @param plotStyle .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$distributionPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$distributionPlotGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$outliers} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$caseDiagnostics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$caseDiagnosticsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$caseDiagnosticsInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$normality} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normalityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$qqNormalityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$qqNormalityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$normalCurvePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$normalCurveGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$normalitySummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normalitySummaryInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$homogeneity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$homogeneityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$homogeneityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$executiveSummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
groupCheck <- function(
    data,
    dep,
    group,
    reportLang = "en",
    alt = "notequal",
    varEq = TRUE,
    showDistributionPlot = FALSE,
    addViolinPlot = FALSE,
    showJitterPoints = FALSE,
    showMeanMarker = TRUE,
    showQQPlots = FALSE,
    qqShowBand = TRUE,
    qqFlagOutliers = TRUE,
    showNormalCurvePlots = FALSE,
    curveBandwidth = 1,
    curveShowRug = FALSE,
    distColorByGroup = TRUE,
    plotPalette = "blueOrange",
    plotStyle = "clean") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("groupCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL))


    options <- groupCheckOptions$new(
        dep = dep,
        group = group,
        reportLang = reportLang,
        alt = alt,
        varEq = varEq,
        showDistributionPlot = showDistributionPlot,
        addViolinPlot = addViolinPlot,
        showJitterPoints = showJitterPoints,
        showMeanMarker = showMeanMarker,
        showQQPlots = showQQPlots,
        qqShowBand = qqShowBand,
        qqFlagOutliers = qqFlagOutliers,
        showNormalCurvePlots = showNormalCurvePlots,
        curveBandwidth = curveBandwidth,
        curveShowRug = curveShowRug,
        distColorByGroup = distColorByGroup,
        plotPalette = plotPalette,
        plotStyle = plotStyle)

    analysis <- groupCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

